local lod_1_distance2 = Mathf.Pow( 6.0, 2.0)
local lod_2_distance2 = Mathf.Pow( 10.0, 2.0)



-- ========================================================


function EmotionalPiece:__init()
    self.controller = nil
    self.isBeCollected = false -- 是否被采集
    self.roleFollow = nil
    self.frameIdx = 0
    self.frameModulo = 20 -- 取模运算, 等待几帧执行一次
end


function EmotionalPiece:__delete()
end



function EmotionalPiece:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end

function EmotionalPiece:Start()
    KTool.SetActive(self.controller.gameObject, true)


    self.transform = self.controller.gameObject.transform


    assert( self.lod_0 and self.lod_1 and self.lod_2 )
    KTool.SetActive( self.lod_0.gameObject, true )

    
    self.idComp = KTool.GetComponent(self.controller.gameObject, typeof(ID))
    assert( isNotNull(self.idComp), "没找到 ID 组件: " .. self.controller.gameObject.name ) 
    assert( self.idComp.id > 1000, "id 值异常, 请对照配表填写" )

    local collider = KTool.GetComponent(self.controller.gameObject, typeof(Collider))
    assert( collider, "必须包含 collider" )



    self.pieceId = self.idComp.id -- 默认都是 1001 开始的 int 值;


    self.srcLocalScale = self.transform.localScale
    self.dstLocalScale = Vector3(
        self.srcLocalScale.x * 1.3,
        self.srcLocalScale.y * 0.3,
        self.srcLocalScale.z * 1.3
    )

    -- must after Awake()
    self.mCameraTF = DreamSpaceCamera.GetMainCamera().transform

    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end




function EmotionalPiece:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    --self.material = nil -- !!! Must !!!
    self:Delete()
end

-- =========================================== Self ================================================ --


function EmotionalPiece:DelayInit()

    cs_coroutine.yield_return( PiecesCollection.WaitInstance( true ) ) -- 等待实例化
    self.piecesCollection = PiecesCollection.GetInstance()   -- 拿到唯一实例

    -- 将自己注册到 piecesCollection:
    -- 在有些测试场景中, 可能不存在 piecesCollection, 此时也要允许程序运行
    if isNotNull( self.piecesCollection )  then 
        self.piecesCollection:RegisteEmotionalPiece( self )
    end 
end



function EmotionalPiece:UpdateLOD()


    self.frameIdx = (self.frameIdx > 100000) and 0 or self.frameIdx + 1
    if (self.frameIdx % self.frameModulo) ~= 0 then 
        return
    end 

    local len2 = (self.transform.position - self.mCameraTF.position).sqrMagnitude
    if len2 > lod_2_distance2 then
        -- 最远, 只开 lod_0
        KTool.SetActive( self.lod_1.gameObject, false )
        KTool.SetActive( self.lod_2.gameObject, false )
        self.frameModulo = 20

    elseif len2 > lod_1_distance2 then
        -- 开启: lod_0, lod_1
        KTool.SetActive( self.lod_1.gameObject, true )
        KTool.SetActive( self.lod_2.gameObject, false )
        self.frameModulo = 10

    else
        -- 最近, 全开
        KTool.SetActive( self.lod_1.gameObject, true )
        KTool.SetActive( self.lod_2.gameObject, true )
        self.frameModulo = 5
    end 
end



function EmotionalPiece:OnTouched( pieceEndTF_ )
    local t = 0.0

    --cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.05 ))

    -- 物体消失
    --self.controller.gameObject:SetActive(false)
    KTool.SetActive( self.controller.gameObject, false )

    pieceEndTF_.position = self.transform.position

    -- pieceEndTF_.gameObject:SetActive(false)
    -- pieceEndTF_.gameObject:SetActive(true)
    KTool.SetActive( pieceEndTF_.gameObject, false )
    KTool.SetActive( pieceEndTF_.gameObject, true )


end



function EmotionalPiece:SetInactive()
    -- 物体消失
    --self.controller.gameObject:SetActive(false)
    KTool.SetActive( self.controller.gameObject, false )
end



